255	    fn ensure_index(&self) -> Arc<HierarchicalIndex> {
256	        if !self.dirty.load(Ordering::Acquire) {
257	            if let Some(index) = self.index.read().as_ref().cloned() {
258	                return index;
259	            }
260	        }
261	
262	        let _guard = self.build_lock.lock();
263	        if !self.dirty.load(Ordering::Acquire) {
264	            if let Some(index) = self.index.read().as_ref().cloned() {
265	                return index;
266	            }
267	        }
268	
269	        let raw = self.raw.read();
270	        let count = raw.ids.len();
271	
272	        if count == 0 {
273	            let empty = Arc::new(HierarchicalIndex {
274	                primary_centroids: vec![0.0; PRIMARY_CLUSTERS * DIM],
275	                secondary_centroids: vec![0.0; PRIMARY_CLUSTERS * SECONDARY_CLUSTERS * DIM],
276	                cluster_offsets: vec![0; PRIMARY_CLUSTERS * SECONDARY_CLUSTERS + 1],
277	                cluster_ids: Vec::new(),
278	                cluster_vectors: Vec::new(),
279	            });
280	            *self.index.write() = Some(empty.clone());
281	            self.dirty.store(false, Ordering::Release);
282	            return empty;
283	        }
284	
285	        let training = collect_training_sample(&raw.vectors, count);
286	        let primary_centroids = run_kmeans(
287	            &training,
288	            training.len() / DIM,
289	            PRIMARY_CLUSTERS,
290	            PRIMARY_KMEANS_ITERS,
291	        );
292	
293	        let sample_primary_assignments: Vec<usize> = training
294	            .par_chunks_exact(DIM)
295	            .map(|sample| nearest_centroid(sample, &primary_centroids, PRIMARY_CLUSTERS))
296	            .collect();
297	
298	        let mut primary_buckets: Vec<Vec<f32>> =
299	            (0..PRIMARY_CLUSTERS).map(|_| Vec::new()).collect();
300	        for (sample_idx, &primary_id) in sample_primary_assignments.iter().enumerate() {
301	            let start = sample_idx * DIM;
302	            primary_buckets[primary_id].extend_from_slice(&training[start..start + DIM]);
303	        }
304	
305	        let secondary_chunks: Vec<Vec<f32>> = primary_buckets
306	            .into_par_iter()
307	            .enumerate()
308	            .map(|(primary_id, bucket)| {
309	                if bucket.is_empty() {
310	                    return duplicate_centroid(
311	                        &primary_centroids[primary_id * DIM..(primary_id + 1) * DIM],
312	                        SECONDARY_CLUSTERS,
313	                    );
314	                }
315	
316	                if bucket.len() / DIM <= SECONDARY_CLUSTERS {
317	                    return expand_bucket_centroids(
318	                        &bucket,
319	                        &primary_centroids[primary_id * DIM..(primary_id + 1) * DIM],
320	                    );
321	                }
322	
323	                run_kmeans(
324	                    &bucket,
325	                    bucket.len() / DIM,
326	                    SECONDARY_CLUSTERS,
327	                    SECONDARY_KMEANS_ITERS,
328	                )
329	            })
330	            .collect();
331	
332	        let mut secondary_centroids =
333	            Vec::with_capacity(PRIMARY_CLUSTERS * SECONDARY_CLUSTERS * DIM);
334	        for chunk in secondary_chunks {
335	            secondary_centroids.extend_from_slice(&chunk);
336	        }
337	
338	        let assignments: Vec<usize> = (0..count)
339	            .into_par_iter()
340	            .map(|idx| {
341	                let start = idx * DIM;
342	                let vector = &raw.vectors[start..start + DIM];
343	                let primary_id = nearest_centroid(vector, &primary_centroids, PRIMARY_CLUSTERS);
344	                let secondary_start = primary_id * SECONDARY_CLUSTERS * DIM;
345	                let secondary_id = nearest_centroid(
346	                    vector,
347	                    &secondary_centroids
348	                        [secondary_start..secondary_start + SECONDARY_CLUSTERS * DIM],
349	                    SECONDARY_CLUSTERS,
350	                );
351	                primary_id * SECONDARY_CLUSTERS + secondary_id
352	            })
353	            .collect();
354	
355	        let total_clusters = PRIMARY_CLUSTERS * SECONDARY_CLUSTERS;
356	        let mut cluster_sizes = vec![0usize; total_clusters];
357	        for &cluster_id in assignments.iter() {
358	            cluster_sizes[cluster_id] += 1;
359	        }
360	
361	        let mut cluster_offsets = vec![0usize; total_clusters + 1];
362	        for idx in 0..total_clusters {
363	            cluster_offsets[idx + 1] = cluster_offsets[idx] + cluster_sizes[idx];
364	        }
365	
366	        let mut cluster_ids = vec![0u64; count];
367	        let mut cluster_vectors = vec![0.0f32; count * DIM];
368	        let mut write_positions = cluster_offsets[..total_clusters].to_vec();
369	
370	        for (vector_idx, &cluster_id) in assignments.iter().enumerate() {
371	            let position = write_positions[cluster_id];
372	            write_positions[cluster_id] += 1;
373	            cluster_ids[position] = raw.ids[vector_idx];
374	
375	            let src = vector_idx * DIM;
376	            let dst = position * DIM;
377	            cluster_vectors[dst..dst + DIM].copy_from_slice(&raw.vectors[src..src + DIM]);
378	        }
379	
380	        drop(raw);
381	
382	        let built = Arc::new(HierarchicalIndex {
383	            primary_centroids,
384	            secondary_centroids,
385	            cluster_offsets,
386	            cluster_ids,
387	            cluster_vectors,
388	        });
389	
390	        *self.index.write() = Some(built.clone());
391	        self.dirty.store(false, Ordering::Release);
392	        built
393	    }
