 39	pub fn run(db: Arc<VectorDB>, addr: &str) -> io::Result<()> {
 40	    let listener = TcpListener::bind(addr)?;
 41	
 42	    loop {
 43	        let (stream, _) = listener.accept()?;
 44	        let db = db.clone();
 45	        thread::spawn(move || {
 46	            let _ = handle_connection(stream, db);
