 51	fn handle_connection(mut stream: TcpStream, db: Arc<VectorDB>) -> io::Result<()> {
 52	    stream.set_nodelay(true)?;
 53	
 54	    let mut buffer = Vec::with_capacity(64 * 1024);
 55	    loop {
 56	        let request = match read_request(&mut stream, &mut buffer) {
 57	            Ok(Some(request)) => request,
 58	            Ok(None) => return Ok(()),
 59	            Err(err) if err.kind() == io::ErrorKind::InvalidData => {
 60	                stream.write_all(BAD_REQUEST_RESPONSE)?;
 61	                return Ok(());
 62	            }
 63	            Err(err) if err.kind() == io::ErrorKind::UnexpectedEof => return Ok(()),
 64	            Err(err) => return Err(err),
 65	        };
 66	
 67	        let outcome = process_request(
 68	            &db,
 69	            &buffer[request.body_start..request.body_end],
 70	            request.route,
 71	        );
 72	        stream.write_all(outcome.response.as_ref())?;
 73	        consume_buffer(&mut buffer, request.consumed);
 74	
 75	        if !outcome.keep_open {
 76	            return Ok(());
 77	        }
 78	    }
 79	}
