180	fn read_request(stream: &mut TcpStream, buffer: &mut Vec<u8>) -> io::Result<Option<ParsedRequest>> {
181	    let mut chunk = [0u8; 64 * 1024];
182	
183	    loop {
184	        if let Some(header_end) = memmem::find(buffer, b"\r\n\r\n") {
185	            let body_start = header_end + 4;
186	            let route = parse_route(buffer)?;
187	            let content_length =
188	                parse_content_length(&buffer[..header_end]).ok_or_else(bad_request_error)?;
189	            let body_end = body_start + content_length;
190	
191	            if buffer.len() >= body_end {
192	                return Ok(Some(ParsedRequest {
193	                    route,
194	                    body_start,
195	                    body_end,
196	                    consumed: body_end,
197	                }));
198	            }
199	        }
200	
201	        let read = stream.read(&mut chunk)?;
202	        if read == 0 {
203	            if buffer.is_empty() {
204	                return Ok(None);
205	            }
206	            return Err(io::Error::new(
207	                io::ErrorKind::UnexpectedEof,
208	                "connection closed before request body completed",
209	            ));
210	        }
211	        buffer.extend_from_slice(&chunk[..read]);
212	    }
213	}
214	
215	fn parse_route(buffer: &[u8]) -> io::Result<Route> {
216	    let request_line_end = memmem::find(buffer, b"\r\n").ok_or_else(bad_request_error)?;
217	    let request_line = &buffer[..request_line_end];
218	    let method_end = memchr(b' ', request_line).ok_or_else(bad_request_error)?;
219	    let path_start = method_end + 1;
220	    let path_end =
221	        path_start + memchr(b' ', &request_line[path_start..]).ok_or_else(bad_request_error)?;
222	
223	    if &request_line[..method_end] != b"POST" {
224	        return Ok(Route::Unknown);
225	    }
226	
227	    Ok(match &request_line[path_start..path_end] {
228	        b"/insert" => Route::Insert,
229	        b"/bulk_insert" => Route::BulkInsert,
230	        b"/search" => Route::Search,
231	        _ => Route::Unknown,
232	    })
233	}
234	
235	fn parse_content_length(header_block: &[u8]) -> Option<usize> {
236	    let request_line_end = memmem::find(header_block, b"\r\n")?;
237	    let mut cursor = request_line_end + 2;
238	
239	    while cursor < header_block.len() {
240	        let line_end = memmem::find(&header_block[cursor..], b"\r\n")
241	            .map(|line_end_rel| cursor + line_end_rel)
242	            .unwrap_or(header_block.len());
243	        let line = &header_block[cursor..line_end];
244	        if let Some(colon) = memchr(b':', line) {
245	            let name = &line[..colon];
246	            if name.eq_ignore_ascii_case(b"content-length") {
247	                let mut value = &line[colon + 1..];
248	                while matches!(value.first(), Some(b' ' | b'\t')) {
249	                    value = &value[1..];
250	                }
251	                return parse_ascii_usize(value);
252	            }
253	        }
254	        cursor = line_end.saturating_add(2);
255	    }
256	
257	    None
258	}
259	
260	fn parse_ascii_usize(bytes: &[u8]) -> Option<usize> {
261	    if bytes.is_empty() {
262	        return None;
263	    }
264	
265	    let mut value = 0usize;
266	    for &byte in bytes {
267	        if !byte.is_ascii_digit() {
268	            return None;
269	        }
270	        value = value.checked_mul(10)?.checked_add((byte - b'0') as usize)?;
271	    }
272	    Some(value)
273	}
274	
275	fn consume_buffer(buffer: &mut Vec<u8>, consumed: usize) {
276	    if consumed >= buffer.len() {
277	        buffer.clear();
278	        return;
279	    }
280	
281	    buffer.copy_within(consumed.., 0);
282	    buffer.truncate(buffer.len() - consumed);
283	}
284	
285	fn bad_request_error() -> io::Error {
286	    io::Error::new(io::ErrorKind::InvalidData, "invalid HTTP request")
287	}

