420	impl TopK {
421	    fn new(limit: usize) -> Self {
422	        Self {
423	            ids: [0u64; MAX_RESULTS],
424	            distances: [f32::MAX; MAX_RESULTS],
425	            len: 0,
426	            limit,
427	        }
428	    }
429	
430	    #[inline(always)]
431	    fn push(&mut self, id: u64, distance: f32) {
432	        if self.limit == 0 {
433	            return;
434	        }
435	
436	        if self.len < self.limit {
437	            self.ids[self.len] = id;
438	            self.distances[self.len] = distance;
439	            self.len += 1;
440	            self.sift_up(self.len - 1);
441	            return;
442	        }
443	
444	        if distance >= self.distances[0] {
445	            return;
446	        }
447	
448	        self.ids[0] = id;
449	        self.distances[0] = distance;
450	        self.sift_down(0);
451	    }
452	
453	    fn into_results(self) -> Vec<SearchResult> {
454	        let mut pairs: Vec<(f32, u64)> = (0..self.len)
455	            .map(|idx| (self.distances[idx], self.ids[idx]))
456	            .collect();
457	        pairs.sort_unstable_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
458	        pairs
459	            .drain(..)
460	            .map(|(distance, id)| SearchResult {
461	                id,
462	                distance: distance as f64,
463	            })
464	            .collect()
465	    }
466	
467	    fn sift_up(&mut self, mut idx: usize) {
468	        while idx > 0 {
469	            let parent = (idx - 1) / 2;
470	            if self.distances[idx] <= self.distances[parent] {
471	                break;
472	            }
473	            self.distances.swap(idx, parent);
474	            self.ids.swap(idx, parent);
475	            idx = parent;
476	        }
477	    }
478	
479	    fn sift_down(&mut self, mut idx: usize) {
480	        loop {
481	            let left = idx * 2 + 1;
482	            let right = left + 1;
483	            let mut largest = idx;
484	
485	            if left < self.len && self.distances[left] > self.distances[largest] {
486	                largest = left;
487	            }
488	            if right < self.len && self.distances[right] > self.distances[largest] {
489	                largest = right;
490	            }
491	            if largest == idx {
492	                break;
493	            }
494	
495	            self.distances.swap(idx, largest);
496	            self.ids.swap(idx, largest);
497	            idx = largest;
498	        }
499	    }
500	}
