524	    fn lookup_request(&self, request_body: &[u8]) -> Option<Bytes> {
525	        let key = RequestCacheKey::from_request_body(request_body)?;
526	        let candidates = self.entries_by_request_key.get(&key)?;
527	        let tail_start = usize::min(request_body.len(), REQUEST_CACHE_PREFIX);
528	        let tail = &request_body[tail_start..];
529	        for candidate in candidates.iter() {
530	            if candidate.tail.as_ref() == tail {
531	                return Some(candidate.response.clone());
532	            }
533	        }
534	        None
535	    }
