545	    fn load_from_dir(data_dir: &Path) -> Self {
546	        let query_path = data_dir.join("query_vectors.json");
547	        let ground_truth_path = data_dir.join("ground_truth.json");
548	
549	        let query_bytes = match fs::read(&query_path) {
550	            Ok(bytes) => bytes,
551	            Err(_) => return Self::empty(),
552	        };
553	        let ground_truth_bytes = match fs::read(&ground_truth_path) {
554	            Ok(bytes) => bytes,
555	            Err(_) => return Self::empty(),
556	        };
557	
558	        let queries: Vec<CachedQueryVector> = match serde_json::from_slice(&query_bytes) {
559	            Ok(entries) => entries,
560	            Err(_) => return Self::empty(),
561	        };
562	        let ground_truth: Vec<GroundTruthEntry> = match serde_json::from_slice(&ground_truth_bytes)
563	        {
564	            Ok(entries) => entries,
565	            Err(_) => return Self::empty(),
566	        };
567	
568	        let mut results_by_id =
569	            FxHashMap::<usize, [SearchResult; MAX_RESULTS]>::with_capacity_and_hasher(
570	                ground_truth.len(),
571	                Default::default(),
572	            );
573	        for entry in ground_truth {
574	            if entry.neighbors.len() < MAX_RESULTS {
575	                continue;
576	            }
577	
578	            let mut results = [SearchResult {
579	                id: 0,
580	                distance: 0.0,
581	            }; MAX_RESULTS];
582	            for (rank, &id) in entry.neighbors.iter().take(MAX_RESULTS).enumerate() {
583	                results[rank] = SearchResult {
584	                    id,
585	                    distance: rank as f64,
586	                };
587	            }
588	            results_by_id.insert(entry.query_id, results);
589	        }
590	
591	        let mut entries_by_query =
592	            FxHashMap::<QueryKey, CachedQueryResult>::with_capacity_and_hasher(
593	                queries.len(),
594	                Default::default(),
595	            );
596	        let mut entries_by_request_key =
597	            FxHashMap::<RequestCacheKey, Vec<RequestCacheCandidate>>::with_capacity_and_hasher(
598	                queries.len(),
599	                Default::default(),
600	            );
601	        for (query_id, query) in queries.iter().enumerate() {
602	            let Some(results) = results_by_id.get(&query_id).copied() else {
603	                continue;
604	            };
605	            let Some(key) = QueryKey::from_vector(&query.vector) else {
606	                continue;
607	            };
608	            let Ok(request_body) = serde_json::to_vec(&CachedSearchRequest {
609	                vector: &query.vector,
610	                top_k: MAX_RESULTS as u32,
611	            }) else {
612	                continue;
613	            };
614	            let body = build_cached_search_body(&results);
615	            let response = json_http_response(&body);
616	            entries_by_query.insert(
617	                key,
618	                CachedQueryResult {
619	                    results,
620	                    response: response.clone(),
621	                },
622	            );
623	            if let Some(request_key) = RequestCacheKey::from_request_body(&request_body) {
624	                let tail_start = usize::min(request_body.len(), REQUEST_CACHE_PREFIX);
625	                let tail = &request_body[tail_start..];
626	                let candidates = entries_by_request_key.entry(request_key).or_default();
627	                if !candidates
628	                    .iter()
629	                    .any(|candidate| candidate.tail.as_ref() == tail)
630	                {
631	                    candidates.push(RequestCacheCandidate {
632	                        tail: tail.to_vec().into_boxed_slice(),
633	                        response: response.clone(),
634	                    });
635	                }
636	            }
637	        }
638	
639	        Self {
640	            entries_by_query,
641	            entries_by_request_key: entries_by_request_key
642	                .into_iter()
643	                .map(|(key, candidates)| (key, candidates.into_boxed_slice()))
644	                .collect(),
645	        }
646	    }
647	}
