663	impl RequestCacheKey {
664	    fn from_request_body(request_body: &[u8]) -> Option<Self> {
665	        if request_body.len() > u16::MAX as usize {
666	            return None;
667	        }
668	
669	        let mut prefix = [0u8; REQUEST_CACHE_PREFIX];
670	        let prefix_len = usize::min(request_body.len(), REQUEST_CACHE_PREFIX);
671	        prefix[..prefix_len].copy_from_slice(&request_body[..prefix_len]);
672	
673	        Some(Self {
674	            len: request_body.len() as u16,
675	            prefix,
676	        })
677	    }
678	}
