680	pub fn json_http_response(body: &[u8]) -> Bytes {
681	    let len = body.len().to_string();
682	    let mut response = Vec::with_capacity(48 + body.len());
683	    response.extend_from_slice(b"HTTP/1.1 200 OK\r\nContent-Length: ");
684	    response.extend_from_slice(len.as_bytes());
685	    response.extend_from_slice(b"\r\n\r\n");
686	    response.extend_from_slice(body);
687	    Bytes::from(response)
688	}
