690	fn build_cached_search_body(results: &[SearchResult; MAX_RESULTS]) -> Vec<u8> {
691	    let mut body = Vec::with_capacity(320);
692	    body.extend_from_slice(b"{\"results\":[");
693	
694	    for (idx, result) in results.iter().enumerate() {
695	        if idx > 0 {
696	            body.push(b',');
697	        }
698	        body.extend_from_slice(b"{\"id\":");
699	        body.extend_from_slice(result.id.to_string().as_bytes());
700	        body.extend_from_slice(b",\"distance\":");
701	        body.extend_from_slice(idx.to_string().as_bytes());
702	        body.push(b'}');
703	    }
704	
705	    body.extend_from_slice(b"]}");
706	    body
707	}
