709	fn collect_training_sample(vectors: &[f32], count: usize) -> Vec<f32> {
710	    let sample_count = usize::min(count, TRAINING_SAMPLES);
711	    let mut sample = Vec::with_capacity(sample_count * DIM);
712	
713	    if sample_count == 0 {
714	        return sample;
715	    }
716	
717	    let step = count as f64 / sample_count as f64;
718	    let mut cursor = 0.0f64;
719	
720	    for _ in 0..sample_count {
721	        let idx = usize::min(cursor as usize, count - 1);
722	        let start = idx * DIM;
723	        sample.extend_from_slice(&vectors[start..start + DIM]);
724	        cursor += step;
725	    }
