730	fn run_kmeans(data: &[f32], points: usize, clusters: usize, iterations: usize) -> Vec<f32> {
731	    let mut centroids = Vec::with_capacity(clusters * DIM);
732	    let step = points as f64 / clusters as f64;
733	    let mut cursor = 0.0f64;
734	
735	    for _ in 0..clusters {
736	        let idx = usize::min(cursor as usize, points - 1);
737	        let start = idx * DIM;
738	        centroids.extend_from_slice(&data[start..start + DIM]);
739	        cursor += step;
740	    }
741	
742	    let mut assignments = vec![0usize; points];
743	
744	    for _ in 0..iterations {
745	        assignments
746	            .par_iter_mut()
747	            .enumerate()
748	            .for_each(|(point_idx, assignment)| {
749	                let start = point_idx * DIM;
750	                *assignment = nearest_centroid(&data[start..start + DIM], &centroids, clusters);
751	            });
752	
753	        let mut sums = vec![0.0f64; clusters * DIM];
754	        let mut counts = vec![0usize; clusters];
755	
756	        for (point_idx, &cluster_id) in assignments.iter().enumerate() {
757	            counts[cluster_id] += 1;
758	            let src = point_idx * DIM;
759	            let dst = cluster_id * DIM;
760	            for dim in 0..DIM {
761	                sums[dst + dim] += data[src + dim] as f64;
762	            }
763	        }
764	
765	        for cluster_id in 0..clusters {
766	            let count = counts[cluster_id];
767	            if count == 0 {
768	                continue;
769	            }
770	
771	            let inv = 1.0f64 / count as f64;
772	            let start = cluster_id * DIM;
773	            for dim in 0..DIM {
774	                centroids[start + dim] = (sums[start + dim] * inv) as f32;
775	            }
776	        }
777	    }
778	
779	    centroids
780	}
