782	fn duplicate_centroid(centroid: &[f32], count: usize) -> Vec<f32> {
783	    let mut result = Vec::with_capacity(count * DIM);
784	    for _ in 0..count {
785	        result.extend_from_slice(centroid);
786	    }
787	    result
788	}
