790	fn expand_bucket_centroids(bucket: &[f32], fallback: &[f32]) -> Vec<f32> {
791	    let points = bucket.len() / DIM;
792	    let mut result = Vec::with_capacity(SECONDARY_CLUSTERS * DIM);
793	
794	    for idx in 0..SECONDARY_CLUSTERS {
795	        if idx < points {
796	            let start = idx * DIM;
797	            result.extend_from_slice(&bucket[start..start + DIM]);
798	        } else {
799	            result.extend_from_slice(fallback);
800	        }
801	    }
802	
803	    result
804	}
