827	    }
828	
829	    let mut worst_idx = 0usize;
830	    for idx in 1..*len {
831	        if distances[idx] > distances[worst_idx] {
832	            worst_idx = idx;
833	        }
834	    }
835	
836	    if distance < distances[worst_idx] {
837	        ids[worst_idx] = id;
838	        distances[worst_idx] = distance;
839	    }
840	}

