 39	/// Send warmup queries to the server. Results are discarded.
 40	pub async fn run_warmup(
 41	    client: &reqwest::Client,
 42	    server_url: &str,
 43	    queries: &[IndexedVector],
 44	    warmup_count: usize,
 45	) {
 46	    let url = format!("{}/search", server_url.trim_end_matches('/'));
 47	    let count = warmup_count.min(queries.len());
 48	
 49	    for q in queries.iter().take(count) {
 50	        let req = SearchRequest {
 51	            vector: q.vector.clone(),
 52	            top_k: 10,
 53	        };
 54	        // Fire and forget – ignore errors during warmup.
 55	        let _ = client.post(&url).json(&req).send().await;
 56	    }
 57	}
 58	
 59	/// Run all queries concurrently with a semaphore-based concurrency limit.
 60	///
 61	/// The query order is shuffled deterministically using the provided `seed`.
 62	/// Each query is sent as a POST `/search` request with `top_k=10`.
 63	/// Returns a `QueryResult` for every query, preserving the original query index.
 64	pub async fn run_queries(
 65	    client: &reqwest::Client,
 66	    server_url: &str,
 67	    queries: &[IndexedVector],
 68	    concurrency: usize,
 69	    seed: u64,
 70	) -> Vec<QueryResult> {
 71	    let url = format!("{}/search", server_url.trim_end_matches('/'));
 72	
 73	    // Build (original_index, query) pairs and shuffle deterministically.
 74	    let mut indexed: Vec<(usize, &IndexedVector)> = queries.iter().enumerate().collect();
 75	    let mut rng = rand::rngs::StdRng::seed_from_u64(seed);
 76	    indexed.shuffle(&mut rng);
 77	
 78	    let semaphore = Arc::new(Semaphore::new(concurrency));
 79	    let client = client.clone();
 80	    let url = Arc::new(url);
 81	
 82	    let mut handles = Vec::with_capacity(indexed.len());
 83	
 84	    for (idx, query) in indexed {
 85	        let permit = semaphore.clone().acquire_owned().await.unwrap();
 86	        let client = client.clone();
 87	        let url = Arc::clone(&url);
 88	        let vector = query.vector.clone();
 89	
 90	        let handle = tokio::spawn(async move {
 91	            let req = SearchRequest {
 92	                vector,
 93	                top_k: 10,
 94	            };
 95	
 96	            let start = Instant::now();
 97	            let resp = client.post(url.as_str()).json(&req).send().await;
 98	            let latency_ms = start.elapsed().as_secs_f64() * 1000.0;
 99	
100	            drop(permit);
101	
102	            let results = match resp {
103	                Ok(r) => r
104	                    .json::<SearchResponse>()
105	                    .await
106	                    .map(|sr| sr.results)
107	                    .unwrap_or_default(),
108	                Err(_) => Vec::new(),
109	            };
110	
111	            QueryResult {
112	                query_index: idx,
113	                results,
114	                latency_ms,
115	            }
116	        });
117	
118	        handles.push(handle);
119	    }
120	
121	    let mut results = Vec::with_capacity(handles.len());
122	    for handle in handles {
123	        if let Ok(qr) = handle.await {
124	            results.push(qr);
125	        }
126	    }
127	
128	    results
129	}
