   276	                primary_centroids: vec![0.0; PRIMARY_CLUSTERS * DIM],
   277	                secondary_centroids: vec![0.0; PRIMARY_CLUSTERS * SECONDARY_CLUSTERS * DIM],
   278	                cluster_offsets: vec![0; PRIMARY_CLUSTERS * SECONDARY_CLUSTERS + 1],
   279	                cluster_ids: Vec::new(),
