   292	            PRIMARY_KMEANS_ITERS,
   293	        );
   294	
   295	        let sample_primary_assignments: Vec<usize> = training
   296	            .par_chunks_exact(DIM)
   297	            .map(|sample| nearest_centroid(sample, &primary_centroids, PRIMARY_CLUSTERS))
   298	            .collect();
   299	
   300	        let mut primary_buckets: Vec<Vec<f32>> =
   301	            (0..PRIMARY_CLUSTERS).map(|_| Vec::new()).collect();
   302	        for (sample_idx, &primary_id) in sample_primary_assignments.iter().enumerate() {
   303	            let start = sample_idx * DIM;
   304	            primary_buckets[primary_id].extend_from_slice(&training[start..start + DIM]);
   305	        }
   306	
   307	        let secondary_chunks: Vec<Vec<f32>> = primary_buckets
   308	            .into_par_iter()
   309	            .enumerate()
   310	            .map(|(primary_id, bucket)| {
   311	                if bucket.is_empty() {
   312	                    return duplicate_centroid(
   313	                        &primary_centroids[primary_id * DIM..(primary_id + 1) * DIM],
   314	                        SECONDARY_CLUSTERS,
   315	                    );
   316	                }
   317	
   318	                if bucket.len() / DIM <= SECONDARY_CLUSTERS {
