   328	                    SECONDARY_CLUSTERS,
   329	                    SECONDARY_KMEANS_ITERS,
   330	                )
   331	            })
   332	            .collect();
   333	
   334	        let mut secondary_centroids =
   335	            Vec::with_capacity(PRIMARY_CLUSTERS * SECONDARY_CLUSTERS * DIM);
   336	        for chunk in secondary_chunks {
   337	            secondary_centroids.extend_from_slice(&chunk);
   338	        }
   339	
   340	        let assignments: Vec<usize> = (0..count)
   341	            .into_par_iter()
   342	            .map(|idx| {
   343	                let start = idx * DIM;
   344	                let vector = &raw.vectors[start..start + DIM];
   345	                let primary_id = nearest_centroid(vector, &primary_centroids, PRIMARY_CLUSTERS);
   346	                let secondary_start = primary_id * SECONDARY_CLUSTERS * DIM;
   347	                let secondary_id = nearest_centroid(
   348	                    vector,
   349	                    &secondary_centroids
   350	                        [secondary_start..secondary_start + SECONDARY_CLUSTERS * DIM],
   351	                    SECONDARY_CLUSTERS,
   352	                );
   353	                primary_id * SECONDARY_CLUSTERS + secondary_id
   354	            })
   355	            .collect();
   356	
   357	        let total_clusters = PRIMARY_CLUSTERS * SECONDARY_CLUSTERS;
   358	        let mut cluster_sizes = vec![0usize; total_clusters];
   359	        for &cluster_id in assignments.iter() {
   360	            cluster_sizes[cluster_id] += 1;
   361	        }
   362	
   363	        let mut cluster_offsets = vec![0usize; total_clusters + 1];
   364	        for idx in 0..total_clusters {
   365	            cluster_offsets[idx + 1] = cluster_offsets[idx] + cluster_sizes[idx];
   366	        }
   367	
   368	        let mut cluster_ids = vec![0u64; count];
