   384	        let built = Arc::new(HierarchicalIndex {
   385	            primary_centroids,
   386	            secondary_centroids,
   387	            cluster_offsets,
   388	            cluster_ids,
   389	            cluster_vectors,
   390	        });
   391	
   392	        *self.index.write() = Some(built.clone());
   393	        self.dirty.store(false, Ordering::Release);
